'use client';
import { Fragment, useEffect, useId, useRef, useState, type CSSProperties, type KeyboardEvent } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useIsoLayoutEffect, useReducedMotion } from '../lib/hooks';
import { Icon, type IconName } from '../lib/icons';
import { useGrow } from '../lib/motion';
import { useHoverGlide } from '../lib/glide';
import '../designme.css';
import './command-palette.css';

export type CommandTone = 'blue' | 'purple' | 'green' | 'orange' | 'red' | 'yellow' | 'pink' | 'teal';
const TONE: Record<CommandTone, string> = { blue: 'pb', purple: 'pl', green: 'pm', orange: 'pp', red: 'pr', yellow: 'py', pink: 'pk', teal: 'pt' };

/** One command in the palette */
export interface CommandPaletteItem {
  /** The group it is listed under, like "Go to" */
  group: string;
  icon: IconName;
  /** What it does, like "Invite a teammate". Typing matches it letter by letter */
  label: string;
  /** Its shortcut, one key per entry, like ['⌘', 'J'] */
  keys?: string[];
  /** A quiet word or two after the label, like "tokens.css". It isn't matched, and gives way first on a narrow palette */
  hint?: string;
  /** The hue of its icon tile, usually one per group. Leave it out for grey */
  tone?: CommandTone;
}

export interface CommandPaletteProps {
  items: CommandPaletteItem[];
  /** What is typed in the box. Leave it out to let the box hold its own */
  query?: string;
  defaultQuery?: string;
  onQueryChange?: (query: string) => void;
  /** Called when a command runs, by click or Enter */
  onRun?: (item: CommandPaletteItem) => void;
  /** Called with the typed text when the last row, "Ask the agent", runs */
  onAsk?: (query: string) => void;
  /** Called by Escape when the box is already empty */
  onClose?: () => void;
  placeholder?: string;
  /** The quiet text at the end of the footer. Defaults to what ran last */
  status?: string;
  /** Puts the cursor in the box when it appears */
  autoFocus?: boolean;
  className?: string;
}

// letters of the query, in order, anywhere in the label
const matches = (label: string, q: string) => {
  const l = label.toLowerCase(); let at = 0;
  for (const ch of q.toLowerCase()) { at = l.indexOf(ch, at); if (at < 0) return false; at++; }
  return true;
};
// every letter the query contains is marked, as on designme.dev
const marked = (label: string, q: string) => {
  if (!q) return label;
  const set = new Set(q.toLowerCase()), out: { t: string; m: boolean }[] = [];
  for (const ch of label) { const m = set.has(ch.toLowerCase()), last = out[out.length - 1]; if (last && !last.m && !m) last.t += ch; else out.push({ t: ch, m }); }
  return out.map((p, i) => p.m ? <mark key={i}>{p.t}</mark> : <Fragment key={i}>{p.t}</Fragment>);
};

/** Jump anywhere or hand a task to the agent from one box. Type to filter, arrows to move, Enter to run, Escape to clear.
    Each command has a tile in its hue and a quiet hint; a command that runs spins its tile for a beat. */
export function CommandPalette({ items, query, defaultQuery = '', onQueryChange, onRun, onAsk, onClose, placeholder = 'Search or ask the agent', status, autoFocus, className }: CommandPaletteProps) {
  const [q, setQ] = useControllable(query, defaultQuery, onQueryChange);
  const v = q.trim();
  const shown = items.filter(it => matches(it.label, v));
  const rows = v ? [...shown, null] : shown; // null is the "Ask the agent" row
  // the highlight goes back to the first row whenever the list changes
  const [hi, setHi] = useState({ at: 0, for: v });
  const at = hi.for === v ? Math.min(hi.at, Math.max(0, rows.length - 1)) : 0;
  const [ran, setRan] = useState('');
  // the row that just ran spins its tile for a beat before the footer says what ran
  const [busy, setBusy] = useState<string>();
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  useEffect(() => () => clearTimeout(timer.current), []);
  // rows that arrive after the first render play a short rise, in a cascade
  const [ready, setReady] = useState(false);
  useEffect(() => { setReady(true); }, []);

  const list = useRef<HTMLDivElement>(null);
  // Clean's one hover: a highlight that glides from row to row (Clean hides the palette's own)
  useHoverGlide(list, '.dm-cpl-i');
  const btns = useRef<(HTMLButtonElement | null)[]>([]);
  const id = useId(), reduce = useReducedMotion();
  const [top, setTop] = useState<{ for: string; px: number }>();
  useIsoLayoutEffect(() => {
    const b = btns.current[at], l = list.current; if (!b || !l) return;
    setTop({ for: v, px: b.offsetTop });
    if (b.offsetTop < l.scrollTop || b.offsetTop + 36 > l.scrollTop + l.clientHeight) l.scrollTo({ top: b.offsetTop - 40, behavior: reduce ? 'auto' : 'smooth' });
  }, [at, v, rows.length, reduce]);

  // while there is more list below, its last row fades out at the edge instead of being cut off by the footer
  const [more, setMore] = useState(false);
  const edge = () => { const l = list.current; if (l) setMore(l.scrollTop + l.clientHeight < l.scrollHeight - 2); };
  useIsoLayoutEffect(edge, [v, rows.length]);

  const move = (d: number) => { if (rows.length) setHi({ at: (at + d + rows.length) % rows.length, for: v }); };
  const run = (i: number) => {
    const row = rows[i];
    if (row === undefined) return;
    if (row) onRun?.(row); else onAsk?.(v);
    const said = row ? 'Ran: ' + row.label : 'Sent to the agent', k = row ? row.group + row.label : '\u0000ask';
    setBusy(k); clearTimeout(timer.current);
    // (nothing in it scales when pressed, owner 18 Nov)
    timer.current = setTimeout(() => { setBusy(b => b === k ? undefined : b); setRan(said); }, reduce ? 0 : 650);
  };
  const key = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'ArrowDown') { move(1); e.preventDefault(); }
    else if (e.key === 'ArrowUp') { move(-1); e.preventDefault(); }
    else if (e.key === 'Enter') run(at);
    else if (e.key === 'Escape') { if (q) setQ(''); else onClose?.(); }
  };

  // no room is kept for a longer list (owner, 18 Nov): the box is as tall as what it shows and eases to its new height as a
  // search narrows or widens it (as grow() on the site)
  const [box, inner] = useGrow();
  let group = '';
  return (
    <div data-dm="" ref={box} className={cx('dm-cpl dm-panel dm-growing', className)}>
      <div ref={inner} className="dm-grow">
      <div className="dm-cpl-in">
        <Icon name="search" />
        {/* the box keeps the focus and points at the highlighted row, so the rows are not tab stops */}
        <input className="dm-cpl-q" placeholder={placeholder} aria-label="Command" spellCheck={false} autoFocus={autoFocus} value={q}
          role="combobox" aria-expanded aria-controls={`${id}-list`} aria-autocomplete="list" aria-activedescendant={rows.length ? `${id}-${at}` : undefined}
          onChange={e => setQ(e.target.value)} onKeyDown={key} />
        <span className="dm-kbd">esc</span>
      </div>
      <div className={cx('dm-cpl-list', more && 'dm-more')} role="listbox" id={`${id}-list`} aria-label="Commands" tabIndex={-1} ref={list} onScroll={edge}>
        {/* a new list starts the highlight afresh, so it jumps into place instead of sliding */}
        <span key={v} className="dm-cpl-hl" style={{ top: top?.for === v ? top.px : undefined }} />
        {rows.map((row, i) => {
          const head = row ? row.group : 'Ask', k = row ? row.group + row.label : '\u0000ask';
          const g = head !== group ? <div className="dm-cpl-g">{(group = head)}</div> : null;
          const tone = row?.tone ? TONE[row.tone] : undefined;
          return (
            <Fragment key={k}>
              {g}
              <button type="button" ref={el => { btns.current[i] = el; }} className={cx('dm-cpl-i', !row && 'dm-ask', i === at && 'dm-hl', ready && 'dm-in')}
                style={ready ? { animationDelay: `${Math.min(i, 6) * 28}ms` } : undefined}
                role="option" id={`${id}-${i}`} tabIndex={-1} aria-selected={i === at} onMouseEnter={() => setHi({ at: i, for: v })} onClick={() => run(i)}>
                <span className="dm-ic" style={tone ? { '--dm-tc': `var(--dm-${tone})`, '--dm-tb': `var(--dm-${tone}-bg)` } as CSSProperties : undefined}>
                  {busy === k ? <span className="dm-spin" aria-hidden="true" /> : <Icon name={row ? row.icon : 'spark'} size="xs" />}
                </span>
                <span className="dm-t">{row ? marked(row.label, v) : <>Ask the agent <span className="dm-q">“{v}”</span></>}</span>
                {row?.hint && <span className="dm-h">{row.hint}</span>}
                {row?.keys && <span className="dm-k">{row.keys.map((k, j) => <span key={j} className="dm-kbd">{k}</span>)}</span>}
                {!row && <span className="dm-kbd dm-ent" aria-hidden="true">↵</span>}
              </button>
            </Fragment>
          );
        })}
      </div>
      {/* what ran last on the left, the keys on the right */}
      <div className="dm-cpl-f dm-muted">
        <span className="dm-cpl-st">{(status ?? ran) && <span key={status ?? ran} className="dm-enter"><span className="dm-dot" aria-hidden="true" />{status ?? ran}</span>}</span>
        <span><span className="dm-kbd">↑</span><span className="dm-kbd">↓</span> move</span>
        <span><span className="dm-kbd">↵</span> run</span>
      </div>
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Command palette ---------- */
/* one quiet box: each command has a tile in its group's hue and a muted hint after its name; a grey highlight glides to the
   row the arrows are on, and a command that runs turns its tile into a spinner for a beat. Its content sits 16px in from every
   edge (owner, 18 Nov): the glass, the group names, the tiles and the footer's words on the left, esc, the shortcuts and the
   footer's keys on the right; the rows' highlight reaches 8px out round them. The list is as tall as what it shows, up to six
   rows or so, and the box eases to its new height as a search narrows it (grow(), centred in its stage): no room is kept */
.dm-cpl{display:flex;flex-direction:column;box-shadow:var(--dm-shadow-pop)}
.dm-cpl-in{display:flex;align-items:center;gap:10px;padding:var(--dm-s-3) var(--dm-s-4);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);color:var(--dm-muted)}
.dm-cpl-q{flex:1;min-width:0;border:0;outline:0;background:transparent;font:inherit;font-size:14px;color:var(--dm-fg);caret-color:var(--dm-accent-fg,var(--dm-fg))}
.dm-cpl-q::placeholder{color:var(--dm-muted)}
/* the line under the search box steps up while it has the focus; a row that takes the focus rings on its own */
.dm-cpl-list{padding:var(--dm-s-2);max-height:236px;overflow-y:auto;position:relative}
/* while there is more list below, its last row fades out at the edge instead of being cut off by the footer */
.dm-cpl-list.dm-more{-webkit-mask-image:linear-gradient(to bottom,#000 calc(100% - 32px),transparent);mask-image:linear-gradient(to bottom,#000 calc(100% - 32px),transparent)}
.dm-cpl-g{font-size:11.5px;color:var(--dm-muted);padding:var(--dm-s-2) var(--dm-s-2) var(--dm-s-1)}
.dm-cpl-i{display:flex;align-items:center;gap:10px;width:100%;height:36px;padding:0 var(--dm-s-2);border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));font-size:13.5px;text-align:left;color:var(--dm-fg);position:relative;z-index:1}
/* rows arrive in a short cascade when the list narrows */
.dm-cpl-i.dm-in{animation:dm-cplin .32s var(--dm-ease) backwards}
@keyframes dm-cplin{from{opacity:0;transform:translateY(4px)}}
.dm-cpl-i .dm-ic{width:24px;height:24px;border-radius:calc(7px * var(--dm-rk-m,var(--dm-rk)));display:grid;place-items:center;flex:none;color:var(--dm-tc,var(--dm-fg2));background:var(--dm-tb,var(--dm-chip));transition:background .2s,color .2s,transform .2s var(--dm-ease)}
.dm-cpl-i.dm-hl .dm-ic{transform:scale(1.06)}
.dm-cpl-i .dm-ic .dm-spin{width:11px;height:11px}
/* a label too long for a narrow palette ends in an ellipsis on its one line, so it never spills out of its row; the hint
   gives way first */
.dm-cpl-i .dm-t{flex:0 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dm-cpl-i .dm-h{flex:1 1 0;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12.5px;color:var(--dm-muted)}
.dm-cpl-i.dm-hl .dm-h{color:var(--dm-fg2)}
.dm-cpl-i .dm-k{margin-left:auto;display:flex;gap:3px;flex:none}
.dm-cpl-i mark{background:transparent;color:var(--dm-accent-fg,var(--dm-accent));font-weight:500}
/* the row that hands the text to the agent: an accent tile, the words in quotes, and Enter shown while it is highlighted */
.dm-cpl-i.dm-ask .dm-ic{background:var(--dm-accent);color:var(--dm-on-accent)}
.dm-cpl-i.dm-ask .dm-q{color:var(--dm-fg2)}
.dm-cpl-i .dm-ent{margin-left:auto;opacity:0;transition:opacity .2s}
.dm-cpl-i.dm-hl .dm-ent{opacity:1}
.dm-cpl-hl{position:absolute;left:var(--dm-s-2);right:var(--dm-s-2);height:36px;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-row);transition:top .25s var(--dm-ease);z-index:0}
/* the footer: what ran last on the left, the keys on the right (they keep their room; the words give way first) */
.dm-cpl-f{display:flex;gap:14px;align-items:center;padding:var(--dm-s-2) var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:11.5px}
.dm-cpl-f>span{flex:none;white-space:nowrap}
.dm-cpl-f .dm-kbd{margin-right:3px}
.dm-cpl-f>.dm-cpl-st{flex:1 1 auto;min-width:0;color:var(--dm-fg2);overflow:hidden;text-overflow:ellipsis}
/* (a footer that lists the keys first keeps what ran at its right end) */
.dm-cpl-f>.dm-cpl-st:last-child{flex:0 1 auto;margin-left:auto}
.dm-cpl-st .dm-dot{color:var(--dm-ok-mark);margin-right:6px;vertical-align:1px}
.dm-cpl-empty{padding:30px 10px;text-align:center;font-size:13px;color:var(--dm-muted)}
:root:not([data-style="soft"],[data-style="clean"]) .dm-cpl-i.dm-hl .dm-ic:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){transform:none}
:root:not([data-style="soft"],[data-style="clean"]) .dm-cpl-i.dm-in:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){animation:dm-bpin .3s var(--dm-ease) backwards}
/* Clean (owner, 18 Nov): the tiles are one neutral grey with a hairline (the groups' hues carry no meaning here), and the row that
   hands the text to the agent has the ink tile of Clean's primary; the letters a search matches read in the text colour, a step
   heavier. The rows' highlight is concentric with the card (14px, 8px in), nothing grows under the pointer, and the footer is an
   off-white foot strip, edge to edge, its words and keys 16px in */
:root[data-style="clean"] .dm-cpl-i .dm-ic,:root [data-style="clean"] .dm-cpl-i .dm-ic,:root [data-style="clean"].dm-cpl-i .dm-ic{color:var(--dm-fg2);background:var(--dm-chip);box-shadow:inset 0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] .dm-cpl-i.dm-ask .dm-ic,:root [data-style="clean"] .dm-cpl-i.dm-ask .dm-ic,:root [data-style="clean"].dm-cpl-i.dm-ask .dm-ic{color:var(--dm-on-btn);background:linear-gradient(180deg,var(--dm-btn-1),var(--dm-btn-2));box-shadow:none}
:root[data-style="clean"] .dm-cpl-i.dm-hl .dm-ic,:root [data-style="clean"] .dm-cpl-i.dm-hl .dm-ic,:root [data-style="clean"].dm-cpl-i.dm-hl .dm-ic{transform:none}
:root[data-style="clean"] .dm-cpl-i.dm-hl:not(.dm-ask) .dm-ic,:root [data-style="clean"] .dm-cpl-i.dm-hl:not(.dm-ask) .dm-ic,:root [data-style="clean"].dm-cpl-i.dm-hl:not(.dm-ask) .dm-ic{background:var(--dm-surface)}
:root[data-style="clean"] .dm-cpl-i mark,:root [data-style="clean"] .dm-cpl-i mark,:root [data-style="clean"].dm-cpl-i mark{color:var(--dm-fg)}
:root[data-style="clean"] :is(.dm-cpl-i,.dm-cpl-hl),:root [data-style="clean"] :is(.dm-cpl-i,.dm-cpl-hl),:root [data-style="clean"]:is(.dm-cpl-i,.dm-cpl-hl){border-radius:calc(var(--dm-r-card) - 8px)}
:root[data-style="clean"] .dm-cpl-hl,:root [data-style="clean"] .dm-cpl-hl,:root [data-style="clean"].dm-cpl-hl{transition:top var(--dm-t) var(--dm-ease)}
:root[data-style="clean"] .dm-cpl-list.dm-hg .dm-cpl-hl,:root [data-style="clean"] .dm-cpl-list.dm-hg .dm-cpl-hl,:root [data-style="clean"].dm-cpl-list.dm-hg .dm-cpl-hl{display:none}
:root[data-style="clean"] .dm-cpl-i.dm-in,:root [data-style="clean"] .dm-cpl-i.dm-in,:root [data-style="clean"].dm-cpl-i.dm-in{animation:dm-clpiece var(--dm-t) var(--dm-ease) backwards}
/* the foot strip is as tall as a strip with a control (44px), so its words sit as far from the card's foot as its sides (16px);
   the list gives up those 10px, so Clean's palette is no taller than Soft's */
:root[data-style="clean"] .dm-cpl-f,:root [data-style="clean"] .dm-cpl-f,:root [data-style="clean"].dm-cpl-f{min-height:calc(28px + 2 * var(--dm-strip-y) + 1px);background:var(--dm-strip);border-top-color:var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .dm-cpl-list,:root [data-style="clean"] .dm-cpl-list,:root [data-style="clean"].dm-cpl-list{max-height:226px}
:root[data-style="clean"] .dm-cpl-f .dm-kbd,:root [data-style="clean"] .dm-cpl-f .dm-kbd,:root [data-style="clean"].dm-cpl-f .dm-kbd{background:var(--dm-surface);box-shadow:inset 0 0 0 1px var(--dm-hair)}
